alter policy "Owner adds print regions" on public.evere_epaper_regions with check (exists (select 1 from public.evere_members where id = (select auth.uid()) and role in ('owner', 'director')));
alter policy "Owner edits print regions" on public.evere_epaper_regions using (exists (select 1 from public.evere_members where id = (select auth.uid()) and role in ('owner', 'director'))) with check (exists (select 1 from public.evere_members where id = (select auth.uid()) and role in ('owner', 'director')));
alter policy "Owner adds print image regions" on public.evere_epaper_image_regions with check (exists (select 1 from public.evere_members where id = (select auth.uid()) and role in ('owner', 'director')));
alter policy "Owner edits print image regions" on public.evere_epaper_image_regions using (exists (select 1 from public.evere_members where id = (select auth.uid()) and role in ('owner', 'director'))) with check (exists (select 1 from public.evere_members where id = (select auth.uid()) and role in ('owner', 'director')));
alter policy "Owner uploads e-paper crops" on storage.objects with check (bucket_id = 'evere-epaper-crops' and exists (select 1 from public.evere_members where id = (select auth.uid()) and role in ('owner', 'director')));
alter policy "Owner reads e-paper crop records" on storage.objects using (bucket_id = 'evere-epaper-crops' and exists (select 1 from public.evere_members where id = (select auth.uid()) and role in ('owner', 'director')));
alter policy "Owner removes e-paper crops" on storage.objects using (bucket_id = 'evere-epaper-crops' and exists (select 1 from public.evere_members where id = (select auth.uid()) and role in ('owner', 'director')));
